// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.api.Test;

/** Controls that parsed BNODE expressions keep the same mapping across non-producing operators. */
class ParsedBlankNodeFilterContinuityTest {
	@Test
	void bindAndFollowingFilterShareTheSameOccurrence() throws Exception {
		List<BindingSet> rows = evaluate("SELECT ?b WHERE { VALUES ?row { 1 2 } "
				+ "BIND(BNODE(\"x\") AS ?b) FILTER(sameTerm(?b, BNODE(\"x\"))) }");

		assertTwoFreshRows(rows, "b");
	}

	@Test
	void successiveFiltersKeepTheBindOccurrence() throws Exception {
		List<BindingSet> rows = evaluate("SELECT ?b WHERE { VALUES ?row { 1 2 } "
				+ "BIND(BNODE(\"x\") AS ?b) "
				+ "FILTER(sameTerm(?b, BNODE(\"x\"))) FILTER(sameTerm(?b, BNODE(\"x\"))) }");

		assertTwoFreshRows(rows, "b");
	}

	@Test
	void repeatedFilterOnlyCallsKeepTheirInputMappings() throws Exception {
		List<BindingSet> rows = evaluate("SELECT ?row WHERE { VALUES ?row { 1 2 } "
				+ "FILTER(sameTerm(BNODE(\"x\"), BNODE(\"x\"))) "
				+ "FILTER(sameTerm(BNODE(\"x\"), BNODE(\"x\"))) }");

		assertEquals(List.of(1, 2), rows.stream()
				.map(row -> ((Literal) row.getValue("row")).intValue())
				.toList());
	}

	@Test
	void groupExpressionInheritsEachBindOccurrence() throws Exception {
		List<BindingSet> rows = evaluate("SELECT (SUM(IF(sameTerm(?b, BNODE(\"x\")), 1, 0)) AS ?count) "
				+ "WHERE { VALUES ?row { 1 2 } BIND(BNODE(\"x\") AS ?b) }");

		assertEquals(1, rows.size());
		assertEquals(2, ((Literal) rows.get(0).getValue("count")).intValue());
	}

	@Test
	void orderExpressionInheritsEachBindOccurrence() throws Exception {
		List<BindingSet> rows = evaluate("SELECT ?row ?b WHERE { VALUES ?row { 1 2 } "
				+ "BIND(BNODE(\"x\") AS ?b) } "
				+ "ORDER BY IF(sameTerm(?b, BNODE(\"x\")), ?row, -?row)");

		assertEquals(List.of(1, 2), rows.stream()
				.map(row -> ((Literal) row.getValue("row")).intValue())
				.toList());
		assertNotEquals(rows.get(0).getValue("b"), rows.get(1).getValue("b"));
	}

	private static List<BindingSet> evaluate(String query) throws Exception {
		var parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		var strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> rows = new ArrayList<>();
		try (var iteration = strategy.evaluate(parsed.getTupleExpr(), EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	private static void assertTwoFreshRows(List<BindingSet> rows, String bindingName) {
		assertEquals(2, rows.size());
		Set<BNode> blankNodes = new HashSet<>();
		for (BindingSet row : rows) {
			BNode value = assertInstanceOf(BNode.class, row.getValue(bindingName));
			assertTrue(blankNodes.add(value), "separate VALUES occurrences require fresh BNODE results");
		}
	}
}
